# Homebrew formula for `work`.
#
# This is a template for the work-cli Homebrew tap. Once GitHub Releases publish
# tarballs (see .github/workflows/release.yml), update the url/sha256 below — or
# keep them generated by your release automation.
#
# Install (once the tap exists):
#   brew tap lucascoelho/work
#   brew install work
#
# Then:
#   work doctor

class Work < Formula
  desc "Isolated multi-context session manager for developers"
  homepage "https://github.com/coelhucas-dev/work-cli"
  url "https://github.com/coelhucas-dev/work-cli/archive/refs/tags/v0.1.0.tar.gz"
  # sha256 "REPLACE_WITH_RELEASE_TARBALL_SHA256"
  license "MIT"
  head "https://github.com/coelhucas-dev/work-cli.git", branch: "main"

  # `work` shells out to a container runtime; recommend OrbStack or Docker.
  depends_on "rust" => :build

  def install
    system "cargo", "install", *std_cargo_args
  end

  test do
    assert_match "work #{version}", shell_output("#{bin}/work --version")
  end
end
